namespace {
constexpr const char* cacheVersion="clap-unfused-8fa0f1c6-cpu-v1-dynamics26";
void require(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
struct DB {
 sqlite3* db=nullptr;
 explicit DB(juce::File file){file.getParentDirectory().createDirectory();require(sqlite3_open(file.getFullPathName().toRawUTF8(),&db)==SQLITE_OK,"Cannot open similarity cache");sqlite3_busy_timeout(db,250);require(sqlite3_exec(db,"PRAGMA journal_mode=WAL; CREATE TABLE IF NOT EXISTS features(path TEXT PRIMARY KEY,mtime INTEGER,size INTEGER,version TEXT,sound BLOB,dynamics BLOB);",nullptr,nullptr,nullptr)==SQLITE_OK,"Cannot initialise similarity cache");require(sqlite3_exec(db,"CREATE TABLE IF NOT EXISTS query_embeddings(path TEXT,mtime INTEGER,size INTEGER,version TEXT,variant TEXT,embedding BLOB,PRIMARY KEY(path,variant));",nullptr,nullptr,nullptr)==SQLITE_OK,"Cannot initialise query cache");}
 ~DB(){if(db)sqlite3_close(db);}
 struct Statement {sqlite3_stmt* p=nullptr;Statement(sqlite3* db,const char* sql){require(sqlite3_prepare_v2(db,sql,-1,&p,nullptr)==SQLITE_OK,"Similarity cache query failed");}~Statement(){sqlite3_finalize(p);}};
 bool get(juce::File f,DrumSimilarity::Features& out){Statement s(db,"SELECT sound,dynamics FROM features WHERE path=? AND mtime=? AND size=? AND version=?");sqlite3_bind_text(s.p,1,f.getFullPathName().toRawUTF8(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s.p,2,f.getLastModificationTime().toMilliseconds());sqlite3_bind_int64(s.p,3,f.getSize());sqlite3_bind_text(s.p,4,cacheVersion,-1,SQLITE_STATIC);if(sqlite3_step(s.p)!=SQLITE_ROW)return false;return decode(s.p,0,out);}
 static bool decode(sqlite3_stmt* s,int offset,DrumSimilarity::Features& out){if(sqlite3_column_bytes(s,offset)!=sizeof(out.sound)||sqlite3_column_bytes(s,offset+1)!=sizeof(out.dynamics))return false;std::memcpy(out.sound.data(),sqlite3_column_blob(s,offset),sizeof(out.sound));std::memcpy(out.dynamics.data(),sqlite3_column_blob(s,offset+1),sizeof(out.dynamics));for(float x:out.sound)if(!std::isfinite(x))return false;for(float x:out.dynamics)if(!std::isfinite(x))return false;return true;}
 void put(juce::File f,const DrumSimilarity::Features& value,int64_t mtime,int64_t size){Statement s(db,"INSERT OR REPLACE INTO features VALUES(?,?,?,?,?,?)");sqlite3_bind_text(s.p,1,f.getFullPathName().toRawUTF8(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s.p,2,mtime);sqlite3_bind_int64(s.p,3,size);sqlite3_bind_text(s.p,4,cacheVersion,-1,SQLITE_STATIC);sqlite3_bind_blob(s.p,5,value.sound.data(),sizeof(value.sound),SQLITE_TRANSIENT);sqlite3_bind_blob(s.p,6,value.dynamics.data(),sizeof(value.dynamics),SQLITE_TRANSIENT);require(sqlite3_step(s.p)==SQLITE_DONE,"Could not save similarity cache");}
 bool variant(juce::File f,const juce::String& id,std::array<float,512>& out){Statement s(db,"SELECT embedding FROM query_embeddings WHERE path=? AND mtime=? AND size=? AND version=? AND variant=?");sqlite3_bind_text(s.p,1,f.getFullPathName().toRawUTF8(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s.p,2,f.getLastModificationTime().toMilliseconds());sqlite3_bind_int64(s.p,3,f.getSize());sqlite3_bind_text(s.p,4,cacheVersion,-1,SQLITE_STATIC);sqlite3_bind_text(s.p,5,id.toRawUTF8(),-1,SQLITE_TRANSIENT);if(sqlite3_step(s.p)!=SQLITE_ROW||sqlite3_column_bytes(s.p,0)!=sizeof(out))return false;std::memcpy(out.data(),sqlite3_column_blob(s.p,0),sizeof(out));for(auto x:out)if(!std::isfinite(x))return false;return true;}
 void putVariant(juce::File f,const juce::String& id,const std::array<float,512>& value,int64_t mtime,int64_t size){Statement s(db,"INSERT OR REPLACE INTO query_embeddings VALUES(?,?,?,?,?,?)");sqlite3_bind_text(s.p,1,f.getFullPathName().toRawUTF8(),-1,SQLITE_TRANSIENT);sqlite3_bind_int64(s.p,2,mtime);sqlite3_bind_int64(s.p,3,size);sqlite3_bind_text(s.p,4,cacheVersion,-1,SQLITE_STATIC);sqlite3_bind_text(s.p,5,id.toRawUTF8(),-1,SQLITE_TRANSIENT);sqlite3_bind_blob(s.p,6,value.data(),sizeof(value),SQLITE_TRANSIENT);require(sqlite3_step(s.p)==SQLITE_DONE,"Cannot cache query variant");}
 std::vector<std::pair<juce::String,DrumSimilarity::Features>> all(std::function<bool()> cancelled){std::vector<std::pair<juce::String,DrumSimilarity::Features>> rows;Statement s(db,"SELECT path,mtime,size,sound,dynamics FROM features WHERE version=?");sqlite3_bind_text(s.p,1,cacheVersion,-1,SQLITE_STATIC);while(sqlite3_step(s.p)==SQLITE_ROW){if(cancelled())break;juce::File f(juce::String::fromUTF8((const char*)sqlite3_column_text(s.p,0)));if(!f.existsAsFile()||f.getLastModificationTime().toMilliseconds()!=sqlite3_column_int64(s.p,1)||f.getSize()!=sqlite3_column_int64(s.p,2))continue;DrumSimilarity::Features v;if(decode(s.p,3,v))rows.emplace_back(f.getFullPathName(),v);}return rows;}
};
std::vector<float> resample(const std::vector<float>& x,double from,double to){if(from==to)return x;std::vector<float> y((size_t)std::ceil(x.size()*to/from)+256);SRC_DATA data{};data.data_in=x.data();data.input_frames=(long)x.size();data.data_out=y.data();data.output_frames=(long)y.size();data.src_ratio=to/from;data.end_of_input=1;require(src_simple(&data,SRC_SINC_FASTEST,1)==0,"Similarity resampling failed");y.resize((size_t)data.output_frames_gen);return y;}
float quantile(std::vector<float> v,double p){if(v.empty())return 0;auto k=(v.size()-1)*p;size_t a=(size_t)k,b=std::min(a+1,v.size()-1);std::nth_element(v.begin(),v.begin()+a,v.end());float low=v[a];std::nth_element(v.begin(),v.begin()+b,v.end());return low+(v[b]-low)*(k-a);}
float median(std::vector<float> v){return std::max(1e-6f,quantile(std::move(v),.5));}
}
juce::File DrumSimilarity::modelFile(){Dl_info location{};if(dladdr((const void*)&DrumSimilarity::modelFile,&location)&&location.dli_fname){auto f=juce::File(juce::String::fromUTF8(location.dli_fname)).getParentDirectory().getParentDirectory().getChildFile("Resources/DrumSimilarity.pt");if(f.existsAsFile())return f;}return juce::File::getCurrentWorkingDirectory().getChildFile("outputs/SliceGroups/Resources/DrumSimilarity.pt");}
bool DrumSimilarity::supported(juce::File f){return f.hasFileExtension("wav;aif;aiff;flac;mp3;ogg");}
DrumSimilarity::Features DrumSimilarity::extract(juce::File file,void* model,std::function<bool()> cancelled,double semitones,bool body){
 juce::AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(file));require(reader&&reader->lengthInSamples>0&&reader->sampleRate>=8000&&reader->sampleRate<=384000,"Unsupported or empty audio");
 // First ten seconds: a bounded sound fingerprint, not a rhythm or full-track analysis.
 int64_t start=body?std::min<int64_t>(reader->lengthInSamples/3,(int64_t)(reader->sampleRate*.15)):0;int length=(int)std::min<int64_t>(reader->lengthInSamples-start,(int64_t)(reader->sampleRate*10));std::vector<float> mono(length);constexpr int block=16384;juce::AudioBuffer<float> audio((int)std::min(2u,reader->numChannels),block);
 for(int at=0;at<length;at+=block){require(!cancelled(),"Cancelled");int n=std::min(block,length-at);require(reader->read(&audio,0,n,start+at,true,true),"Cannot read similarity audio");for(int i=0;i<n;++i){float value=0;for(int ch=0;ch<audio.getNumChannels();++ch)value+=audio.getSample(ch,i);mono[at+i]=std::isfinite(value)?value/audio.getNumChannels():0;}}
 double mean=std::accumulate(mono.begin(),mono.end(),0.)/mono.size();for(auto& x:mono)x-=mean;auto signal=resample(mono,reader->sampleRate*std::pow(2.,semitones/12),48000);if(signal.size()>480000)signal.resize(480000);require(!signal.empty(),"Empty similarity audio");double rms=0;for(auto x:signal)rms+=x*x;rms=std::sqrt(rms/signal.size());require(rms>1e-7,"Silent audio has no searchable sound");float gain=(float)std::min(10.,.1/rms);for(auto& x:signal)x*=gain;
 std::vector<float> padded(480000);size_t copies=padded.size()/signal.size();for(size_t i=0;i<copies;++i)std::copy(signal.begin(),signal.end(),padded.begin()+i*signal.size());require(!cancelled(),"Cancelled");Features out;char error[512]{};require(sg_similarity_process(model,padded.data(),out.sound.data(),error,sizeof(error))!=0,error);require(!cancelled(),"Cancelled");
 auto dynamics=resample(mono,reader->sampleRate,22050);double power=0;for(float x:dynamics)power+=x*x;float normal=(float)(1/std::sqrt(std::max(1e-14,power/dynamics.size())));for(auto& x:dynamics)x*=normal;std::vector<float> absolute(dynamics.size());std::transform(dynamics.begin(),dynamics.end(),absolute.begin(),[](float x){return std::abs(x);});int index=0;for(double p:{.5,.9,.99,.999})out.dynamics[index++]=std::log(quantile(absolute,p)+1e-6f);out.dynamics[index++]=std::log(*std::max_element(absolute.begin(),absolute.end())+1e-6f);
 for(double ms:{2.,10.,40.}){int frame=(int)std::round(ms*.001*22050);std::vector<float> values;for(size_t a=0;a+frame<=dynamics.size();a+=frame){double sum=0;for(int i=0;i<frame;++i)sum+=dynamics[a+i]*dynamics[a+i];values.push_back((float)std::sqrt(sum/frame));}if(values.empty())values.push_back(0);for(double p:{.1,.25,.5,.75,.9})out.dynamics[index++]=std::log(quantile(values,p)+1e-5f);double avg=std::accumulate(values.begin(),values.end(),0.)/values.size(),variance=0;for(auto v:values)variance+=(v-avg)*(v-avg);out.dynamics[index++]=(float)std::sqrt(variance/values.size());}
 std::vector<float> differences;for(size_t i=1;i<dynamics.size();++i)differences.push_back(std::abs(dynamics[i]-dynamics[i-1]));for(double p:{.5,.9,.99})out.dynamics[index++]=std::log(quantile(differences,p)+1e-6f);return out;
}
DrumSimilarity::Scores DrumSimilarity::rank(const Features& reference,const std::vector<std::pair<juce::String,Features>>& rows,Mode mode,const std::vector<std::array<float,512>>& alternatives,const std::function<bool()>& cancelled){
 Scores result;if(rows.empty())return result;std::array<double,26> means{},scales{};for(auto& row:rows){if(cancelled&&cancelled())return {};for(int d=0;d<26;++d)means[d]+=row.second.dynamics[d]/(double)rows.size();}for(auto& row:rows){if(cancelled&&cancelled())return {};for(int d=0;d<26;++d){double x=row.second.dynamics[d]-means[d];scales[d]+=x*x/rows.size();}}std::vector<float> deviations;for(auto& s:scales){s=std::sqrt(s);deviations.push_back(s);}double floor=std::max(1e-5f,median(deviations)*.1f);for(auto& s:scales)s=std::max(floor,s);
 auto distances=[&](const Features& a,const Features& b){double dot=0,dyn=0;for(int i=0;i<512;++i)dot+=a.sound[i]*b.sound[i];for(int i=0;i<26;++i){double x=(a.dynamics[i]-b.dynamics[i])/scales[i];dyn+=x*x;}return std::make_pair((float)std::max(0.,1-dot),(float)std::sqrt(dyn/26));};
 // Estimate distance scales from a bounded deterministic sample of candidate pairs.
 std::vector<float> neural,dynamic;size_t n=std::min<size_t>(rows.size(),128);for(size_t a=0;a<n;++a)for(size_t b=a+1;b<n;++b){if(cancelled&&cancelled())return {};auto d=distances(rows[a*rows.size()/n].second,rows[b*rows.size()/n].second);neural.push_back(d.first);dynamic.push_back(d.second);}float ns=median(neural),ds=median(dynamic);for(auto& row:rows){if(cancelled&&cancelled())return {};auto d=distances(reference,row.second);if(mode==Mode::General){for(auto& embedding:alternatives){double dot=0;for(int i=0;i<512;++i)dot+=embedding[i]*row.second.sound[i];d.first=std::min(d.first,(float)std::max(0.,1-dot));}result[row.first]=.9f*d.first/ns+.1f*d.second/ds;}else result[row.first]=.5f*(d.first/ns+d.second/ds);}return result;
}
DrumSimilarity::DrumSimilarity(juce::File cacheRoot):Thread("Sound similarity preparation"),root(cacheRoot){}
DrumSimilarity::~DrumSimilarity(){signalThreadShouldExit();++generation;++batchGeneration;notify();stopThread(-1);}
void DrumSimilarity::launch(){if(!isThreadRunning())startThread(juce::Thread::Priority::background);notify();}
DrumSimilarity::State DrumSimilarity::state()const{std::lock_guard<std::mutex> lock(mutex);return current;}
juce::File DrumSimilarity::referenceForQuery()const{std::lock_guard<std::mutex> lock(mutex);return query;}
void DrumSimilarity::prepare(juce::Array<juce::File> files){{std::lock_guard<std::mutex> lock(mutex);pending.addArray(files);if(!current.busy){current.completed=current.failed=current.cached=current.total=0;current.lastError.clear();}current.busy=true;current.paused=false;current.message="Preparing sound similarity…";++current.revision;}launch();}
void DrumSimilarity::find(juce::File file,Mode mode,bool pitchTolerant){{std::lock_guard<std::mutex> lock(mutex);query=file;queryPending=true;current.mode=mode;current.pitchTolerant=pitchTolerant&&mode==Mode::General;current.queryBusy=true;current.queryCompleted=0;current.queryTotal=current.mode==Mode::Drums?1:current.pitchTolerant?26:2;current.message="Finding similar sounds…";++generation;++current.revision;}launch();}
void DrumSimilarity::clear(){std::lock_guard<std::mutex> lock(mutex);++generation;query=juce::File();queryPending=false;current.queryBusy=false;current.reference=juce::File();current.scores.reset();++current.resultRevision;++current.revision;}
void DrumSimilarity::pause(bool value){{std::lock_guard<std::mutex> lock(mutex);current.paused=value;current.message=value?"Sound similarity preparation paused":"Preparing sound similarity…";++current.revision;}notify();}
void DrumSimilarity::cancel(){std::lock_guard<std::mutex> lock(mutex);++batchGeneration;pending.clear();current.busy=false;current.paused=false;current.message="Similarity preparation cancelled; completed sounds kept";++current.revision;notify();}
void DrumSimilarity::run(){
 pthread_set_qos_class_self_np(QOS_CLASS_BACKGROUND,0);void* model=nullptr;std::unique_ptr<DB> db;auto ensure=[&]{if(!db)db=std::make_unique<DB>(root.getChildFile("drum-similarity.db"));};auto features=[&](juce::File f,std::function<bool()> cancelled){ensure();Features value;if(db->get(f,value))return value;if(!model){char error[512]{};model=sg_similarity_create(modelFile().getFullPathName().toRawUTF8(),error,sizeof(error));require(model!=nullptr,error);}auto mtime=f.getLastModificationTime().toMilliseconds(),size=f.getSize();value=extract(f,model,cancelled);require(!cancelled(),"Cancelled");require(f.getLastModificationTime().toMilliseconds()==mtime&&f.getSize()==size,"Audio changed during preparation");db->put(f,value,mtime,size);return value;};
 while(!threadShouldExit()){
  juce::File ref;juce::Array<juce::File> batch;uint64_t token=0,batchToken=0;Mode mode=Mode::Drums;bool pitchTolerant=false;
  {std::lock_guard<std::mutex> lock(mutex);if(queryPending){queryPending=false;current.queryBusy=true;ref=query;token=generation;mode=current.mode;pitchTolerant=current.pitchTolerant;}else if(!current.paused&&!pending.isEmpty()){batch.swapWith(pending);batchToken=batchGeneration;}}
  if(ref!=juce::File())try{
   auto cancelled=[&]{return threadShouldExit()||generation!=token;};auto value=features(ref,cancelled);
   auto progress=[&](int done){std::lock_guard<std::mutex> lock(mutex);if(!cancelled()){current.queryCompleted=done;current.message="Finding similar sounds: "+juce::String(done)+" / "+juce::String(current.queryTotal);++current.revision;}};progress(1);
   std::vector<std::array<float,512>> alternatives;
   auto variant=[&](int semitones,bool body){require(!cancelled(),"Cancelled");auto id=juce::String(body?"body150-v1:":"pitch-v1:")+juce::String(semitones);std::array<float,512> vector{};
    bool computed=!db->variant(ref,id,vector);if(computed){if(!model){char error[512]{};model=sg_similarity_create(modelFile().getFullPathName().toRawUTF8(),error,sizeof(error));require(model!=nullptr,error);}auto mtime=ref.getLastModificationTime().toMilliseconds(),size=ref.getSize();try{vector=extract(ref,model,cancelled,semitones,body).sound;}catch(const std::exception& e){if(body&&juce::String(e.what()).contains("Silent audio"))vector=value.sound;else throw;}require(!cancelled(),"Cancelled");require(ref.getLastModificationTime().toMilliseconds()==mtime&&ref.getSize()==size,"Audio changed during similarity search");db->putVariant(ref,id,vector,mtime,size);}
    alternatives.push_back(vector);progress(1+(int)alternatives.size());return computed;
   };
   if(mode==Mode::General){variant(0,true);if(pitchTolerant)for(int semitone=-12;semitone<=12;++semitone)if(semitone){bool computed=variant(semitone,false);if(cancelled())break;if(computed)wait(10);}}
   auto rows=db->all(cancelled);if(cancelled())continue;auto scores=std::make_shared<Scores>(rank(value,rows,mode,alternatives,cancelled));scores->erase(ref.getFullPathName());
   std::lock_guard<std::mutex> lock(mutex);if(!cancelled()){current.queryBusy=false;current.reference=ref;current.scores=scores;++current.resultRevision;current.message=scores->empty()?"No prepared matches. Right-click an audio folder → Prepare similarity search":"Similar to "+ref.getFileName()+" · "+juce::String(scores->size())+" prepared sounds";++current.revision;}
  }catch(const std::exception& e){std::lock_guard<std::mutex> lock(mutex);if(generation==token){current.queryBusy=false;current.message="Similarity: "+juce::String(e.what());++current.revision;}}
  else if(!batch.isEmpty()){
   auto cancelled=[&]{return threadShouldExit()||batchGeneration!=batchToken;};std::set<juce::String> paths;std::vector<juce::File> files;
   for(auto item:batch){if(cancelled())break;if(item.isDirectory()){juce::RangedDirectoryIterator iterator(item,true,"*",juce::File::findFiles);for(auto entry:iterator){if(cancelled())break;auto f=entry.getFile();if(supported(f)&&paths.insert(f.getFullPathName()).second)files.push_back(f);}}else if(supported(item)&&paths.insert(item.getFullPathName()).second)files.push_back(item);}
   {std::lock_guard<std::mutex> lock(mutex);current.total=current.completed+(int)files.size();++current.revision;}
   for(size_t i=0;i<files.size()&&!cancelled();++i){
    bool yield=false;{std::lock_guard<std::mutex> lock(mutex);yield=queryPending||current.paused;if(yield){for(size_t j=i;j<files.size();++j)pending.add(files[j]);break;}}
    try{ensure();Features v;bool cached=db->get(files[i],v);if(!cached)features(files[i],cancelled);std::lock_guard<std::mutex> lock(mutex);if(!cancelled()){++current.completed;if(cached)++current.cached;}}
    catch(const std::exception& e){std::lock_guard<std::mutex> lock(mutex);if(!cancelled()){++current.completed;++current.failed;current.lastError=e.what();}}
    {std::lock_guard<std::mutex> lock(mutex);if(!cancelled()){current.message="Sound similarity: "+juce::String(current.completed)+" / "+juce::String(current.total)+" · "+files[i].getFileName();++current.revision;}}
    wait(10);
   }
   {std::lock_guard<std::mutex> lock(mutex);if(!cancelled()&&pending.isEmpty()){current.busy=false;current.message="Similarity ready: "+juce::String(current.completed-current.failed)+" sounds ("+juce::String(current.cached)+" cached, "+juce::String(current.failed)+" skipped)"+(current.failed?"; "+current.lastError:juce::String());if(query!=juce::File())queryPending=true;++current.revision;}}
  }else wait(100);
 }
 if(model)sg_similarity_destroy(model);
}
